/* ===== 📞 SCOT clean-up (Admin Console → Business → SCOT list) — 26-Oct-2026 =====
 * The Sirs remove parties CRM should not call (no orders expected). The row leaves the SCOT sheet; its values are kept in
 * Script Properties SCOT_RM_* (no new sheet) so it can be restored, and Tally / "add all" never put it back. */
function propJsonGet_(p) { const P = PropertiesService.getScriptProperties(), n = Number(P.getProperty(p + 'N') || 0); if (!n) return {};
  let s = ''; for (let i = 0; i < n; i++) s += P.getProperty(p + i) || ''; try { return JSON.parse(s) || {}; } catch (e) { return {}; } }
function propJsonPut_(p, o) { const P = PropertiesService.getScriptProperties(), s = JSON.stringify(o), old = Number(P.getProperty(p + 'N') || 0), w = {}, parts = [];
  for (let i = 0; i < s.length; i += 8000) parts.push(s.slice(i, i + 8000)); parts.forEach((x, i) => w[p + i] = x); w[p + 'N'] = String(parts.length);
  P.setProperties(w); for (let i = parts.length; i < old; i++) P.deleteProperty(p + i); try { MOD_PROPS = null; } catch (e) {} }
function scotRemovedGet_() { return propJsonGet_('SCOT_RM_'); }
function adminScotList(token) {
  const u = poUser_(token); if (!pcSir_(u)) throw new Error('Only Bhupinder Sir and Rishu Sir');
  const now = new Date(), D = scotData_(now.getFullYear(), now.getMonth()), cust = {}, T = tallyFreqGet_(), f = d => Utilities.formatDate(d, 'Asia/Kolkata', 'dd-MMM-yy');
  crmCustomers_().forEach(c => cust[normName_(c.name)] = c);
  const rows = D.rows.map(r => { const k = normName_(r.name), c = cust[k] || {}, t = T[k] || {};
    let lb = c.last instanceof Date ? c.last : null; if (t.last && (!lb || t.last > lb.getTime())) lb = new Date(t.last);
    return { name: r.name, phone: r.phone, owner: r.owner, cls: r.cls, avg: r.avg || '', freq: r.freq || '', callDay: r.callDay || '', n6: c.n6 || t.n6 || 0,
      lastBill: lb ? f(lb) : '', days: lb ? Math.round((now - lb) / 864e5) : null, lastCall: r.last ? f(r.last) : '', tally: !!T[k] }; });
  const R = scotRemovedGet_();
  return { rows, removed: Object.keys(R).map(k => ({ name: R[k].name, by: R[k].by, at: f(new Date(R[k].at)), reason: R[k].reason })).sort((a, b) => a.name.localeCompare(b.name)) };
}
function adminScotRemove(token, names, reason) {
  rw_(getUser_(token)); const u = poUser_(token); if (!pcSir_(u)) throw new Error('Only Bhupinder Sir and Rishu Sir');
  reason = String(reason || '').trim(); if (!reason) throw new Error('Write why (e.g. no orders expected)');
  const want = {}; (names || []).forEach(n => want[normName_(n)] = 1); if (!Object.keys(want).length) throw new Error('Select at least one party');
  const lock = LockService.getScriptLock(); lock.waitLock(20000);
  try {
    const sh = crmSheet_(CRM_SCOT_TAB), n = sh.getLastRow() - 3; if (n < 1) return adminScotList(token);
    const A = sh.getRange(4, 1, n, 8).getValues(), X = sh.getRange(4, CRM_X0, n, 2).getValues(), R = scotRemovedGet_(), del = [];
    A.forEach((r, i) => { const k = normName_(r[0]); if (!String(r[0]).trim() || !want[k]) return;
      R[k] = { name: String(r[0]), data: r.map(v => v instanceof Date ? v.getTime() : v), link: X[i], by: u.name, at: Date.now(), reason }; del.push(i + 4); });
    propJsonPut_('SCOT_RM_', R);
    del.sort((a, b) => b - a).forEach(r => sh.deleteRow(r));
    if (sh.getMaxRows() < 600) sh.insertRowsAfter(sh.getMaxRows(), 600 - sh.getMaxRows());
    console.log('SCOT: ' + del.length + ' removed by ' + u.name + ' · ' + reason);
  } finally { lock.releaseLock(); }
  try { scotRefresh_(); } catch (e) {}
  return adminScotList(token);
}
function adminScotRestore(token, names) {
  rw_(getUser_(token)); const u = poUser_(token); if (!pcSir_(u)) throw new Error('Only Bhupinder Sir and Rishu Sir');
  const R = scotRemovedGet_(), sh = crmSheet_(CRM_SCOT_TAB); let n = 0;
  (names || []).forEach(nm => { const k = normName_(nm), x = R[k]; if (!x) return;
    const r = Math.max(sh.getLastRow(), 3) + 1; sh.getRange(r, 2).setNumberFormat('@');
    sh.getRange(r, 1, 1, 8).setValues([x.data]); sh.getRange(r, CRM_X0, 1, 2).setValues([x.link || ['', '']]); delete R[k]; n++; });
  propJsonPut_('SCOT_RM_', R);
  try { scotRefresh_(); } catch (e) {}
  console.log('SCOT: ' + n + ' restored by ' + u.name);
  return adminScotList(token);
}

