/* 📞 SCOT list (26-Oct-2026): Sirs remove parties CRM should not call (no orders expected) · restore anytime */
function scotAdm(){
  if (!S.scl && !S.sclBusy) { S.sclBusy = 1; call('adminScotList', S.token).then(x => { S.scl = x; S.sclBusy = 0; render(); }).catch(e => { S.scl = { err: (e && e.message) || String(e) }; S.sclBusy = 0; render(); }); }
  const D = S.scl; if (!D) return '<div class="card"><p>Loading SCOT list…</p></div>'; if (D.err) return '<div class="card"><p style="color:#b42335">'+esc(D.err)+'</p></div>';
  S.scsel = S.scsel || {}; const f = S.scf || 'quiet', q = (S.scq || '').toLowerCase();
  const isQuiet = r => r.days == null || r.days > 90;
  const L = D.rows.filter(r => (f === 'all' || (f === 'quiet' ? isQuiet(r) : f === 'never' ? r.days == null : false)) && (!q || r.name.toLowerCase().includes(q)))
    .sort((a, b) => (b.days == null ? 1e9 : b.days) - (a.days == null ? 1e9 : a.days) || a.name.localeCompare(b.name));
  const nSel = Object.keys(S.scsel).filter(k => S.scsel[k]).length;
  const chip = (k, l, n) => '<button data-scf="'+k+'" class="'+(f===k?'on':'')+'">'+l+' · '+n+'</button>';
  let h = '<div class="card"><h2>📞 SCOT list — who CRM calls</h2><p style="color:var(--muted);margin:2px 0 10px">Remove parties from whom no order is expected. They leave the SCOT sheet and CRM stops calling them. Tally updates will not add them back. You can restore them below.</p>'
    + '<div class="sub2">' + chip('quiet','No bill in 90+ days / never', D.rows.filter(isQuiet).length) + chip('never','Never billed', D.rows.filter(r => r.days == null).length) + chip('all','All on SCOT', D.rows.length) + '</div>'
    + '<div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center;margin:10px 0"><input id="scq" placeholder="Search party" value="'+esc(S.scq||'')+'" style="flex:1;min-width:160px;height:36px;border:1px solid var(--line);border-radius:10px;padding:0 10px">'
    + '<button class="hbtn" id="scAll" style="background:#eef2f8;color:#0f2547">Select shown ('+L.length+')</button><button class="hbtn" id="scRm" style="background:#dc2626;color:#fff" '+(nSel?'':'disabled')+'>🗑 Remove '+nSel+' from SCOT</button></div>'
    + '<div style="max-height:520px;overflow:auto;border:1px solid var(--line);border-radius:12px"><table style="width:100%"><tr><th></th><th>Party</th><th>Last bill</th><th>Bills (6 m)</th><th>Buys every</th><th>Avg order</th><th>Owner</th><th>Last call</th></tr>'
    + L.slice(0, 400).map(r => '<tr><td><input type="checkbox" data-scn="'+esc(r.name)+'" '+(S.scsel[r.name]?'checked':'')+'></td><td><b>'+esc(r.name)+'</b>'+(r.cls?' <span class="pill">'+esc(r.cls)+'</span>':'')+'<div style="font-size:11px;color:var(--muted)">'+esc(r.phone||'no phone')+'</div></td>'
      + '<td style="color:'+(r.days==null?'#94a3b8':r.days>90?'#dc2626':'inherit')+'">'+(r.lastBill?esc(r.lastBill)+' <span style="font-size:11px">('+r.days+' d)</span>':'never')+'</td><td class="r">'+(r.n6||0)+'</td><td>'+(r.freq?esc(r.freq)+' d':'—')+'</td><td class="r">'+(r.avg?RS(r.avg):'—')+'</td><td>'+esc(r.owner||'—')+'</td><td>'+esc(r.lastCall||'—')+'</td></tr>').join('')
    + '</table></div>' + (L.length > 400 ? '<p style="color:var(--muted);font-size:12px">Showing 400 — search to narrow.</p>' : '') + '</div>';
  h += '<div class="card" style="margin-top:14px"><h2>↩ Removed from SCOT · '+D.removed.length+'</h2>' + (D.removed.length ? D.removed.map(x => '<div class="dl"><div class="w"><b>'+esc(x.name)+'</b><span>'+esc(x.reason||'')+' · by '+esc(x.by||'')+' on '+esc(x.at)+'</span></div><button class="hbtn" data-scr="'+esc(x.name)+'" style="background:#eef2f8;color:#0f2547">Restore</button></div>').join('') : '<p style="color:var(--muted)">Nobody removed yet.</p>') + '</div>';
  setTimeout(scotAdmWire, 0); return h;
}
function scotAdmWire(){
  document.querySelectorAll('[data-scf]').forEach(b => b.onclick = () => { S.scf = b.dataset.scf; render(); });
  const qi = $('scq'); if (qi) qi.oninput = () => { S.scq = qi.value; clearTimeout(S.scqT); S.scqT = setTimeout(() => { render(); const z = $('scq'); if (z) { z.focus(); z.setSelectionRange(z.value.length, z.value.length); } }, 350); };
  document.querySelectorAll('[data-scn]').forEach(c => c.onchange = () => { S.scsel[c.dataset.scn] = c.checked; render(); });
  const a = $('scAll'); if (a) a.onclick = () => { document.querySelectorAll('[data-scn]').forEach(c => S.scsel[c.dataset.scn] = true); render(); };
  const rm = $('scRm'); if (rm) rm.onclick = async () => { const names = Object.keys(S.scsel).filter(k => S.scsel[k]); if (!names.length) return;
    const why = prompt('Remove ' + names.length + ' part' + (names.length>1?'ies':'y') + ' from SCOT — why? (e.g. no orders expected / one-time buyer / closed)', 'No orders expected'); if (!why) return;
    rm.disabled = true; rm.textContent = 'Removing…'; try { S.scl = await call('adminScotRemove', S.token, names, why); S.scsel = {}; toast(names.length + ' removed from SCOT'); } catch (e) { toast((e && e.message) || e); } render(); };
  document.querySelectorAll('[data-scr]').forEach(b => b.onclick = async () => { b.disabled = true; try { S.scl = await call('adminScotRestore', S.token, [b.dataset.scr]); toast(b.dataset.scr + ' is back on SCOT'); } catch (e) { toast((e && e.message) || e); } render(); });
}
